            const STEP_FRAC = 0.5;      // a step advances half a stem length
            const WANDER = 0.40;        // random-walk amplitude, radians
            const UP_BIAS = 0.28;       // restoring force back toward vertical
            // A new sprout travels outward before the restoring force takes hold,
            // so a fork reads as a branching plant instead of a second stem running
            // parallel to its parent. SPREAD_STEPS is how long that lasts and
            // SPREAD_PUSH is how hard it leans while it does.
            const SPREAD_STEPS = 8;
            const SPREAD_PUSH = 0.17;
            // Branching is scaled to the room a vine actually has, because the
            // column is not one shape: it is ~413x1315 on the Projects panel and
            // ~413x192 on Stats, where min-height alone sets the box. A fixed
            // 12-step refractory is 8% of a tall vine's life and a quarter of a
            // short one's, so a short column got about one fork per stem and read
            // as bare sticks with gaps between them -- measured at 37.7% of the
            // width carrying material against 94.3% on the tall column.
            //
